WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_r_distance'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '路程比', 'kp-trv-r-distance', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "路程比"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定理：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "相遇问题中，路程比是划分总路线的黄金法则。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "两人相向而行相遇，通过某人的行程，或者偏离中点的距离倒推全程。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "只要是同时出发相遇，用的时间必定相同。"}]}, {"type": "katexBlock", "attrs": {"content": "\\frac{S_{甲}}{S_{乙}} = \\frac{V_{甲}}{V_{乙}}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忘记算中点偏离的两倍：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "甲比乙多走了 20 米，说明相遇点偏离中点 10 米。因为甲多出来的这部分，是他过了中点多走的，而这部分正是乙没走到中点差的。一正一负，相差是偏离中点距离的两倍！"}]}]}]}$$ AS jsonb), NULL, '路程比的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "路程比"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_r_distance", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
